import datetime
import re

from ta_moler.events.egate.genericepcsim_lineevent import GenericEPCSIMLineEvent


class ChangeState(GenericEPCSIMLineEvent):
    """ChangeStateToConfigured event class."""

    def __init__(self, connection, egate_state="configured", till_occurs_times=-1, runner=None):
        """
        Event for 'ChangeStateToConfigured.'.

        :param connection: moler connection to device, terminal when command is executed
        :param egate_state: egate state. Could be one of ['INIT', 'CONFIGURED', 'STARTED', 'ACTIVE']
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        self._egate_state = egate_state.upper()
        self._validate_state_parameter()

        # 13:32:49.436 CSI: SM: CHANGE STATE: CONFIGURED
        self._re_detect_pattern = re.compile(f"CHANGE STATE: (?P<STATE>{self._egate_state})")

        super(ChangeState, self).__init__(
            connection=connection, runner=runner, till_occurs_times=till_occurs_times, detect_patterns=[self._re_detect_pattern], match="any"
        )

    def _validate_state_parameter(self):
        possible_values = ["INIT", "CONFIGURED", "STARTED", "ACTIVE"]
        if self._egate_state not in possible_values:
            raise ValueError(f"state parameter '{self._egate_state}' is not supported. Possible values: {possible_values}")


EVENT_OUTPUT = """
13:32:49.436 CSI: SM: CHANGE STATE: CONFIGURED
"""

EVENT_KWARGS = {"till_occurs_times": 1}

